function validate([n, limit]) {
  if (!Number.isInteger(n) || n < 1 || n > 1000000) return 'n is an integer from 1 to 10^6.';
  if (!Number.isInteger(limit) || limit < 1 || limit > 1000000) return 'limit is an integer from 1 to 10^6.';
  return null;
}

