function distributeCandies(n, limit) {
  let ways = 0;
  for (let first = 0; first <= Math.min(n, limit); first++) {
    const rest = n - first;
    const low = Math.max(0, rest - limit);
    const high = Math.min(limit, rest);
    if (low <= high) {
      ways += high - low + 1;
    }
  }
  return ways;
}

