function distributeCandies(n, limit) {
  // Inclusion-exclusion over the children forced above the limit.
  const pairs = m => (m >= 2 ? (m * (m - 1)) / 2 : 0);
  return pairs(n + 2) - 3 * pairs(n - limit + 1) + 3 * pairs(n - 2 * limit) - pairs(n - 3 * limit - 1);
}

