function generate(rand, size) {
  if (size === 'large') {
    const n = 500000 + Math.floor(rand() * 500001);
    const limit = Math.min(1000000, Math.max(1, Math.floor(n * (0.3 + rand() * 0.9))));
    return [n, limit];
  }
